function strt(e){Shelly.call("KVS.Get",{key:"SmartHeatingSys"+e},(function(t,l,n,i){0===l&&t&&delS(JSON.parse(t.value),i.id)}),{id:e})}function delS(e,t){let l=e.ExistingSchedule;l>0&&Shelly.call("Schedule.Delete",{id:l},(function(e,t,l,n){if(0!==t){print("Script #"+n.scId,"schedule ",n.id," deletion by watchdog failed.");return}print("Script #"+n.scId,"schedule ",n.id," deleted by watchdog."),updK(n.sDat,n.scId)}),{id:l,scId:t,sDat:e})}function updK(e,t){e.ExistingSchedule=0,Shelly.call("KVS.set",{key:"SmartHeatingSys"+t,value:JSON.stringify(e)})}Shelly.addStatusHandler((function(e){"script"===e.name&&!e.delta.running&&strt(e.id)}));
